 3 | pragma solidity >=0.8.0;
 4 | 
 5 | import "../../interfaces/IConcentratedLiquidityPool.sol";
 6 | import "./ConcentratedLiquidityPosition.sol";
 7 | 
 8 | /// @notice Trident Concentrated Liquidity Pool periphery contract that combines non-fungible position management and staking.
 9 | contract ConcentratedLiquidityPoolManager is ConcentratedLiquidityPosition {
10 |     event AddIncentive(IConcentratedLiquidityPool indexed pool, Incentive indexed incentive);
11 |     event ReclaimIncentive(IConcentratedLiquidityPool indexed pool, uint256 indexed incentiveId);
12 |     event Subscribe(uint256 indexed positionId, uint256 indexed incentiveId);
13 |     event ClaimReward(uint256 indexed positionId, uint256 indexed incentiveId, address indexed recipient);
14 | 
15 |     struct Incentive {
16 |         address owner;
17 |         address token;
18 |         uint256 rewardsUnclaimed;
19 |         uint160 secondsClaimed; // @dev x128.
20 |         uint32 startTime;
21 |         uint32 endTime;
22 |         uint32 expiry;
23 |     }
24 | 
25 |     struct Stake {
26 |         uint160 secondsInsideLast; // @dev x128.
27 |         bool initialized;
28 |     }
29 | 
30 |     mapping(IConcentratedLiquidityPool => uint256) public incentiveCount;
31 |     mapping(IConcentratedLiquidityPool => mapping(uint256 => Incentive)) public incentives;
32 |     mapping(uint256 => mapping(uint256 => Stake)) public stakes;
33 | 
34 |     constructor(address wETH, address _masterDeployer) ConcentratedLiquidityPosition(wETH, _masterDeployer) {}
35 | 
36 |     function addIncentive(IConcentratedLiquidityPool pool, Incentive memory incentive) public {
37 |         uint32 current = uint32(block.timestamp);
38 |         require(current <= incentive.startTime, "ALREADY_STARTED");
39 |         require(current <= incentive.endTime, "ALREADY_ENDED");
40 |         require(incentive.startTime < incentive.endTime, "START_PAST_END");
41 |         require(incentive.endTime + 5 weeks < incentive.expiry, "END_PAST_BUFFER");
42 |         require(incentive.rewardsUnclaimed != 0, "NO_REWARDS");
43 |         incentives[pool][incentiveCount[pool]++] = incentive;
44 |         _transfer(incentive.token, msg.sender, address(this), incentive.rewardsUnclaimed, false);
45 |         emit AddIncentive(pool, incentive);
46 |     }
47 | 
48 |     /// @dev Withdraws any unclaimed incentive rewards.
